const dom = new JSDOM(html, {
  runScripts: 'dangerously',
  pretendToBeVisual: true,
  resources: 'usable'
})
const { window } = dom

await new Promise(r => setTimeout(r, 600))

const doc = window.document
const nodes = [...doc.querySelectorAll(selector)]
